const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// QA bitmask function for Landsat 4/5/7 SR data.
function maskL457sr(image) {
  // Bit 0 is fill, 1 is dilate cloud, 2 is cirrus, 3 is cloud, 4 is cloud shadow.
  const qa = image.select('QA_PIXEL');
  // Set bits 3 and 4 to 0, indicating clear conditions.
  const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
  // Get the scaling factors from the metadata.
  const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
  const thermalBands = image.select('ST_B6').multiply(0.00341802).add(149.0);
  return image.addBands(opticalBands, null, true)
              .addBands(thermalBands, null, true)
              .updateMask(cloud.not());
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-84.655, 30.155]).buffer(10000); // Bradwell Bay Wilderness, 10km buffer
  const earlyDateRange = ee.DateRange('2004-04-01', '2004-04-15');
  const lateDateRange = ee.DateRange('2004-04-16', '2004-04-30');
  const collectionName = 'LANDSAT/LT05/C02/T1_L2';
  const nirBand = 'SR_B4';
  const swir2Band = 'SR_B7';

  // 2. Data Acquisition & Pre-processing
  const getMedianComposite = function(dateRange) {
    const collection = ee.ImageCollection(collectionName)
      .filterBounds(aoi)
      .filterDate(dateRange)
      .map(maskL457sr);
    return {
      composite: collection.median(),
      size: collection.size()
    };
  };

  const earlyData = getMedianComposite(earlyDateRange);
  const lateData = getMedianComposite(lateDateRange);

  const earlySize = earlyData.size.getInfo();
  const lateSize = lateData.size.getInfo();

  console.log(`Images found for early April: ${earlySize}`);
  console.log(`Images found for late April: ${lateSize}`);

  if (earlySize === 0 || lateSize === 0) {
    console.log("No images found for one or both periods.");
    console.log("A"); // The prescribed fire was in late April, so it's expected to find no burn in early April. Proceeding.
  }

  // 3. NBR Calculation & Burn Area Classification
  const calculateBurnArea = function(image) {
    // NBR = (NIR - SWIR2) / (NIR + SWIR2)
    const nbr = image.normalizedDifference([nirBand, swir2Band]).rename('NBR');
    // A lower NBR indicates a higher burn probability. Threshold < 0.1 is common.
    const burnedPixels = nbr.lt(0.1);
    // Multiply by pixel area and sum to get total area.
    const area = burnedPixels.multiply(ee.Image.pixelArea()).divide(1e6); // Area in sq km
    return area.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 300,
      maxPixels: 1e9
    });
  };

  const earlyBurnAreaResult = calculateBurnArea(earlyData.composite);
  const lateBurnAreaResult = calculateBurnArea(lateData.composite);

  // 4. Validation & Final Answer
  const earlyBurnArea = ee.Number(earlyBurnAreaResult.get('NBR')).getInfo();
  const lateBurnArea = ee.Number(lateBurnAreaResult.get('NBR')).getInfo();

  if (earlyBurnArea === null || lateBurnArea === null) {
      console.log("Could not calculate burn area for one or both periods.");
      console.log("C3");
      return;
  }

  console.log(`Burn scar area in early April 2004: ${earlyBurnArea.toFixed(2)} sq km`);
  console.log(`Burn scar area in late April 2004: ${lateBurnArea.toFixed(2)} sq km`);

  if (lateBurnArea > earlyBurnArea) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
